            return "DOWNTREND_EXCEPTION_ONLY"
        if regime == "N/A":
            return "N/A"
        return "UNCLASSIFIED_NO_RISK_EXPANSION"

    def _e1r_risk_budget_for_regime(regime: str) -> dict:
